              if key.lower() in x.lower(): markers.append((key,x[:180].replace('\n',' '))); break
    print('\n',f.name)
    print(' first',first,'last',last,'tokens',inp,out,'prs',sorted(prs),'types',dict(types))
    print(' comments',comments)
    print(' markers',markers[-8:])
